            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Kraus", Text = "Einen Aphorismus zu schreiben, wenn man es kann, ist oft schwer. Viel leichter ist es, einen Aphorismus zu schreiben, wenn man es nicht kann.", Author = "Karl Kraus" },
