            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Kraus", Text = "Es gibt nur eine Möglichkeit, sich vor der Maschine zu retten. Das ist, sie zu benützen. Nur mit dem Auto kommt man zu sich.", Author = "Karl Kraus" },
