            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Kraus", Text = "Vielleicht ginge es besser, wenn die Menschen Maulkörbe und die Hunde Gesetze bekämen, wenn die Menschen an der Leine und die Hunde an der Religion geführt würden. Die Hundswut könnte in gleichem Maße abnehmen wie die Politik.", Author = "Karl Kraus" },
