            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Kraus", Text = "Der Sport ist ein Sohn des Fortschritts, und er trägt schon auf eigene Faust zur Verdummung der Familie bei.", Author = "Karl Kraus" },
