            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Kraus", Text = "Die anständigen Frauen empfinden es als die größte Dreistigkeit, wenn man ihnen unter das Bewusstsein greift.", Author = "Karl Kraus" },
